{
  "name": "皮秒延时模块",
  "name_en": "Picosecond Delay Module",
  "manufacturer": "Micro Photon Devices",
  "description": "这是一种用于对触发信号或脉冲输出进行超短时间延迟控制的电子定时模块，可在皮秒量级设置延迟，并可配置输出脉宽、触发电平、触发沿和分频等参数。它常用于时间分辨测量、激光与探测器同步、门控触发和精密时序调整实验。",
  "description_en": "This is an electronic timing module used to apply ultra-short delays to trigger signals or pulse outputs, with delay settings in the picosecond range. It also allows configuration of output pulse width, trigger level, trigger edge, and frequency division. It is commonly used in time-resolved measurements, synchronization of lasers and detectors, gated triggering, and precision timing adjustment experiments.",
  "tag_hints": [
    "picosecond delay",
    "timing synchronization",
    "trigger delay",
    "pulse generation",
    "time-resolved measurement",
    "laser detector synchronization",
    "frequency divider"
  ],
  "actions": [
    {
      "action_name": "auto-GenStartMetadata",
      "description": "生成设备启动元数据",
      "description_en": "generate startup metadata for the device"
    },
    {
      "action_name": "auto-register",
      "description": "注册设备控制与状态项",
      "description_en": "register device control and state items"
    },
    {
      "action_name": "auto-send_command",
      "description": "向设备发送串口命令",
      "description_en": "send a serial command to the device"
    },
    {
      "action_name": "auto-delay",
      "description": "获取/设置延迟",
      "description_en": "get/set delay"
    },
    {
      "action_name": "auto-pulse_width",
      "description": "获取/设置输出脉宽",
      "description_en": "get/set output pulse width"
    },
    {
      "action_name": "auto-trigger_level",
      "description": "获取/设置触发电平",
      "description_en": "get/set trigger level"
    },
    {
      "action_name": "auto-frequency_divider",
      "description": "获取/设置分频系数",
      "description_en": "get/set frequency divider"
    },
    {
      "action_name": "auto-edge",
      "description": "获取/设置触发沿",
      "description_en": "get/set trigger edge"
    },
    {
      "action_name": "auto-io",
      "description": "获取/设置输出使能状态",
      "description_en": "get/set output enable state"
    },
    {
      "action_name": "auto-Enable",
      "description": "开启输出",
      "description_en": "enable output"
    },
    {
      "action_name": "auto-Disable",
      "description": "关闭输出",
      "description_en": "disable output"
    },
    {
      "action_name": "auto-echo_mode",
      "description": "获取/设置回显模式",
      "description_en": "get/set echo mode"
    },
    {
      "action_name": "auto-high_speed_mode",
      "description": "获取/设置高速模式",
      "description_en": "get/set high-speed mode"
    },
    {
      "action_name": "auto-GetTemperature",
      "description": "查询当前温度",
      "description_en": "query current temperature"
    },
    {
      "action_name": "auto-GetDelay",
      "description": "查询当前延迟设定",
      "description_en": "query current delay setting"
    },
    {
      "action_name": "auto-GetPulseWidth",
      "description": "查询当前输出脉宽设定",
      "description_en": "query current output pulse width setting"
    },
    {
      "action_name": "auto-GetTriggerLevel",
      "description": "查询当前触发电平设定",
      "description_en": "query current trigger level setting"
    },
    {
      "action_name": "auto-GetEdge",
      "description": "查询当前触发沿设定",
      "description_en": "query current trigger edge setting"
    },
    {
      "action_name": "auto-GetIO",
      "description": "查询当前输出使能状态",
      "description_en": "query current output enable state"
    },
    {
      "action_name": "auto-GetFrequencyDivider",
      "description": "查询当前分频系数",
      "description_en": "query current frequency divider"
    },
    {
      "action_name": "auto-GetMaxDelay",
      "description": "查询最大可设延迟",
      "description_en": "query maximum available delay"
    }
  ]
}

